import { useState, useEffect } from 'react'
import { Link } from 'react-router-dom'
import Navbar from '../components/Navbar'

const MOCK_ROOMS = [
  {
    id: 1,
    title: "Modern Coworking Space",
    description: "Open collaborative workspace with high-speed internet, comfortable seating, and natural lighting.",
    room_type: "Coworking",
    capacity: 20,
    price_per_hour: 15,
    image_url: "data:image/jpeg;base64,",
    amenities: ["WiFi", "Coffee", "Whiteboard"],
    posted_by: "Admin",
    posted_date: "5/15/2026"
  },
  {
    id: 2,
    title: "Executive Conference Room",
    description: "Professional conference room with video conferencing technology.",
    room_type: "Conference",
    capacity: 12,
    price_per_hour: 50,
    image_url: "data:image/jpeg;base64,",
    amenities: ["Video Conferencing", "Whiteboard", "TV Screen"],
    posted_by: "Admin",
    posted_date: "5/20/2026"
  },
  {
    id: 3,
    title: "Private Office",
    description: "Quiet private office space ideal for focused work.",
    room_type: "Private",
    capacity: 2,
    price_per_hour: 25,
    image_url: "data:image/jpeg;base64,",
    amenities: ["WiFi", "Desk", "Storage"],
    posted_by: "Admin",
    posted_date: "5/25/2026"
  },
  {
    id: 4,
    title: "Creative Studio",
    description: "Spacious creative studio perfect for photoshoots and workshops.",
    room_type: "Studio",
    capacity: 15,
    price_per_hour: 35,
    image_url: "data:image/jpeg;base64,",
    amenities: ["Natural Light", "Equipment", "WiFi"],
    posted_by: "Admin",
    posted_date: "6/1/2026"
  },
  {
    id: 5,
    title: "Meeting Room Small",
    description: "Compact meeting room for 4-6 people.",
    room_type: "Meeting",
    capacity: 6,
    price_per_hour: 30,
    image_url: "data:image/jpeg;base64,",
    amenities: ["TV Screen", "Whiteboard", "WiFi"],
    posted_by: "Admin",
    posted_date: "6/2/2026"
  },
  {
    id: 6,
    title: "Large Event Space",
    description: "Spacious event venue for workshops and seminars.",
    room_type: "Event",
    capacity: 50,
    price_per_hour: 100,
    image_url: "data:image/jpeg;base64,",
    amenities: ["Projector", "Sound System", "WiFi"],
    posted_by: "Admin",
    posted_date: "6/3/2026"
  }
]

export default function Catalog() {
  const [rooms, setRooms] = useState([])
  const [loading, setLoading] = useState(true)
  const [searchTerm, setSearchTerm] = useState('')
  const [activeFilter, setActiveFilter] = useState('All Types')
  
  const [showMoreFilters, setShowMoreFilters] = useState(false)
  const [capacityMin, setCapacityMin] = useState('')
  const [priceMax, setPriceMax] = useState(100)
  const [priceValue, setPriceValue] = useState(100)

  useEffect(() => {
    setTimeout(() => {
      setRooms(MOCK_ROOMS)
      setLoading(false)
    }, 500)
  }, [])

  const resetFilters = () => {
    setSearchTerm('')
    setActiveFilter('All Types')
    setCapacityMin('')
    setPriceMax(100)
    setPriceValue(100)
  }

  const filteredRooms = rooms.filter(room => {
    const matchesSearch = searchTerm === '' ||
      room.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      room.description.toLowerCase().includes(searchTerm.toLowerCase())
    
    const matchesType = activeFilter === 'All Types' || room.room_type === activeFilter
    const matchesCapacity = capacityMin === '' || room.capacity >= parseInt(capacityMin)
    const matchesPrice = room.price_per_hour <= priceMax
    
    return matchesSearch && matchesType && matchesCapacity && matchesPrice
  })

  const filters = ['All Types', 'Coworking', 'Conference', 'Private', 'Studio', 'Meeting', 'Event']

  if (loading) {
    return (
      <>
        <Navbar />
        <div className="loader">
          <div className="spinner"></div>
        </div>
      </>
    )
  }

  return (
    <>
      <Navbar />
      <div className="container">
        <div className="hero">
          <h1>Find Your Perfect Workspace</h1>
          <p>Browse and book office spaces, meeting rooms, and coworking areas</p>
        </div>

        <div className="search-section">
          <div className="search-bar">
            <span className="search-icon"></span>
            <input
              type="text"
              placeholder="Search rooms..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>

          <div className="filters-row">
            <div className="filters">
              {filters.map(filter => (
                <button
                  key={filter}
                  className={`filter-btn ${activeFilter === filter ? 'active' : ''}`}
                  onClick={() => setActiveFilter(filter)}
                >
                  {filter}
                </button>
              ))}
            </div>
            
            <button 
              className={`more-filters-btn ${showMoreFilters ? 'active' : ''}`}
              onClick={() => setShowMoreFilters(!showMoreFilters)}
            >
              {showMoreFilters ? 'Less Filters' : 'More Filters'}
            </button>
          </div>

          {showMoreFilters && (
            <div className="more-filters-panel">
              <div className="filter-group">
                <label>Minimum Capacity (people)</label>
                <input
                  type="number"
                  className="capacity-input"
                  placeholder="Any"
                  value={capacityMin}
                  onChange={(e) => setCapacityMin(e.target.value)}
                  min="1"
                />
              </div>

              <div className="filter-group">
                <label>Max Price per Hour: ${priceValue}</label>
                <input
                  type="range"
                  className="price-slider"
                  min="0"
                  max="100"
                  value={priceMax}
                  onChange={(e) => {
                    setPriceMax(parseInt(e.target.value))
                    setPriceValue(parseInt(e.target.value))
                  }}
                />
                <div className="price-labels">
                  <span>$0</span>
                  <span>$25</span>
                  <span>$50</span>
                  <span>$75</span>
                  <span>$100+</span>
                </div>
              </div>

              <button className="reset-filters-btn" onClick={resetFilters}>
                Reset All Filters
              </button>
            </div>
          )}

          <div className="spaces-count">
            {filteredRooms.length} spaces available
          </div>
        </div>

        <div className="grid">
          {filteredRooms.map(room => (
            <div key={room.id} className="room-card">
              <img src={room.image_url} alt={room.title} className="room-image" />
              
              <div className="room-content">
                {/* Без лишних обёрток — напрямую классы */}
                <h3 className="room-title">{room.title}</h3>
                <p className="room-type">{room.room_type}</p>
                <p className="room-description">
                  {room.description.substring(0, 100)}...
                </p>
                
                <div className="room-info">
                  <span className="capacity">{room.capacity} people</span>
                  <span className="price">${room.price_per_hour}<small>/hr</small></span>
                </div>
                
                <div className="amenities">
                  {room.amenities.map((item, idx) => (
                    <span key={idx} className="amenity">{item}</span>
                  ))}
                </div>
                
                <div className="posted-by">
                  Posted by {room.posted_by} on {room.posted_date}
                </div>
                
                <div className="book-btn-wrapper">
                  <Link to={`/catalog/${room.id}`}>
                    <button className="book-btn">
                      Book Now
                    </button>
                  </Link>
                </div>
              </div>
            </div>
          ))}
        </div>
        
        {filteredRooms.length === 0 && (
          <div className="no-results">
            Nothing found. Try changing filters or search.
          </div>
        )}
      </div>
    </>
  )
}